class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {

        Map<Integer, List<Integer>> adj = new HashMap();

        for (int i = 0; i < numCourses; i++) {
            adj.computeIfAbsent(i, k -> new ArrayList());
        }

        for (int i = 0; i < prerequisites.length; i++) {
            int[] prereq = prerequisites[i];
            adj.get(prereq[1]).add(prereq[0]);
        }

        boolean[] checked = new boolean[numCourses];
        boolean[] path = new boolean[numCourses];
        for (int node: adj.keySet()) {
            if (dfs(adj, node, path, checked)) {
                return false;
            }
        }
        return true;
    }

    private boolean dfs(Map<Integer, List<Integer>> adj, int node, boolean[] path, boolean[] checked) {
        // bottom cases
        if (checked[node])
            // this node has been checked, no cycle would be formed with this node.
            return false;

        if (path[node]) {
            return true;
        }

        if (!adj.containsKey(node)) {
            return false;
        }
        path[node] = true;

        boolean ret = false;

        for(int neighbor : adj.get(node)) {
            ret = dfs(adj, neighbor, path, checked);
            if (ret) {
                break;
            }
        }
        path[node] = false;
        checked[node] = true;
        return ret;
    }
}

class Solution {
    private static final int[][] DIRECTIONS = new int[][]{{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        // Check if input is empty
        if (heights.length == 0 || heights[0].length == 0) {
            return new ArrayList<>();
        }

        // Save initial values to parameters
        int numRows = heights.length;
        int numCols = heights[0].length;
        boolean[][] pacificReachable = new boolean[numRows][numCols];
        boolean[][] atlanticReachable = new boolean[numRows][numCols];

        // Loop through each cell adjacent to the oceans and start a DFS
        for (int i = 0; i < numRows; i++) {
            dfs(heights, i, 0, pacificReachable);
            dfs(heights, i, numCols - 1, atlanticReachable);
        }
        for (int i = 0; i < numCols; i++) {
            dfs(heights, 0, i, pacificReachable);
            dfs(heights, numRows - 1, i, atlanticReachable);
        }

        // Find all cells that can reach both oceans
        List<List<Integer>> commonCells = new ArrayList<>();
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                if (pacificReachable[i][j] && atlanticReachable[i][j]) {
                    commonCells.add(List.of(i, j));
                }
            }
        }
        return commonCells;
    }

    private void dfs(int[][] heights, int row, int col, boolean[][] reachable) {
        // This cell is reachable, so mark it
        reachable[row][col] = true;
        for (int[] dir : DIRECTIONS) { // Check all 4 directions
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            // Check if new cell is within bounds
            if (newRow < 0 || newRow >= heights.length || newCol < 0 || newCol >= heights[0].length) {
                continue;
            }
            // Check that the new cell hasn't already been visited
            if (reachable[newRow][newCol]) {
                continue;
            }
            // Check that the new cell has a higher or equal height,
            // So that water can flow from the new cell to the old cell
            if (heights[newRow][newCol] < heights[row][col]) {
                continue;
            }
            // If we've gotten this far, that means the new cell is reachable
            dfs(heights, newRow, newCol, reachable);
        }
    }
}
